<div class="page-heading"><div><span class="eyebrow">Inbox</span><h1>Messages & notifications</h1><p>Application decisions, document feedback and important reminders.</p></div></div><section class="card inbox-card"><?php if(!$notifications):?><div class="empty-state"><span>✉</span><h2>Your inbox is clear</h2><p>New application updates will appear here.</p></div><?php endif?><?php foreach($notifications as $notification):?><article class="inbox-item <?= $notification['read_at']?'':'unread' ?>"><span class="inbox-icon"><?= $notification['type']==='status'?'↗':'✉' ?></span><div><div><b><?= e($notification['title']) ?></b><time><?= format_date($notification['created_at'],true) ?></time></div><p><?= e($notification['message']) ?></p><?php if($notification['action_url']):?><a href="<?= url(ltrim($notification['action_url'],'/')) ?>">View details →</a><?php endif?></div></article><?php endforeach?></section>
